import com.google.firebase.crashlytics.buildtools.gradle.CrashlyticsExtension
import java.util.Properties

plugins {
    alias(libs.plugins.androidApplication)
    alias(libs.plugins.composeCompiler)
    alias(libs.plugins.jetbrains.kotlin.serialization)
    alias(libs.plugins.googleServices)
    alias(libs.plugins.firebaseCrashlytics)
    // Baseline Profile consumer: profiles generated by :baselineprofile land in
    // src/release/generated/baselineProfiles/ (baseline-prof.txt + startup-prof.txt).
    alias(libs.plugins.baselineprofile)
}

// ─── Read local.properties ────────────────────────────────────────────────────
val localProperties = project.rootProject.file("local.properties")
val localProps = Properties().apply {
    if (localProperties.exists()) load(localProperties.inputStream())
}

android {
    // Namespace differs from applicationId: the R class package is .app-specific,
    // while applicationId (the Play Store package) stays "com.antonchuraev.aichecklists".
    // This avoids R class namespace collision with composeApp which uses the base namespace.
    namespace = "com.antonchuraev.aichecklists.app"
    compileSdk = libs.versions.android.compileSdk.get().toInt()

    defaultConfig {
        applicationId = "com.antonchuraev.aichecklists"
        minSdk = libs.versions.android.minSdk.get().toInt()
        targetSdk = libs.versions.android.targetSdk.get().toInt()
        versionCode = 91
        versionName = "1.23.0"

        testInstrumentationRunner = "com.antonchuraev.aichecklists.TestRunner"

        // Test Orchestrator - isolate tests with clearPackageData
        testInstrumentationRunnerArguments["clearPackageData"] = "true"

        // BuildConfig fields — Amplitude key set per build type below.
        // NOTE: Gemini API key intentionally NOT here. AI calls go through Cloud Functions
        // (server holds the key in Secret Manager), so the APK never ships a key.
        buildConfigField("String", "GOOGLE_WEB_CLIENT_ID", "\"${localProps.getProperty("GOOGLE_WEB_CLIENT_ID", "")}\"")
    }

    testOptions {
        // Enable Test Orchestrator for test isolation
        execution = "ANDROIDX_TEST_ORCHESTRATOR"

        // Disable animations to prevent flaky tests
        animationsDisabled = true

        unitTests {
            isIncludeAndroidResources = true
            isReturnDefaultValues = true
        }
    }

    buildFeatures {
        buildConfig = true
    }

    packaging {
        resources {
            excludes += "/META-INF/{AL2.0,LGPL2.1}"
            excludes += "/META-INF/LICENSE.md"
            excludes += "/META-INF/LICENSE-notice.md"
        }
    }

    signingConfigs {
        create("release") {
            val keystorePath = localProps.getProperty("KEYSTORE_FILE", "")
            if (keystorePath.isNotEmpty()) {
                storeFile = rootProject.file(keystorePath)
                storePassword = localProps.getProperty("KEYSTORE_PASSWORD", "")
                keyAlias = localProps.getProperty("KEY_ALIAS", "gisti")
                keyPassword = localProps.getProperty("KEY_PASSWORD", "")
            }
        }
    }

    buildTypes {
        getByName("debug") {
            buildConfigField("String", "AMPLITUDE_KEY", "\"${localProps.getProperty("AMPLITUDE_DEBUG_KEY", "")}\"")
        }
        getByName("release") {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
            signingConfig = signingConfigs.getByName("release")
            buildConfigField("String", "AMPLITUDE_KEY", "\"${localProps.getProperty("AMPLITUDE_KEY", "")}\"")
        }

        // Build types the androidx.baselineprofile plugin would otherwise create on its own
        // (nonMinifiedRelease = profile generation, benchmarkRelease = Macrobenchmark). Declared
        // here so we control what initWith(release) would leak into them; the plugin then only
        // forces isDebuggable=false / isProfileable=true / minify flags on top. Never shipped.
        listOf("nonMinifiedRelease", "benchmarkRelease").forEach { name ->
            create(name) {
                initWith(getByName("release"))
                matchingFallbacks += listOf("release")
                // Debug key, always: installs over the dev-device debug build (same signature,
                // no INSTALL_FAILED_UPDATE_INCOMPATIBLE) and its SHA-1 is already registered for
                // Google sign-in / App Check. Does not depend on the keystore. The install itself
                // keeps data, but the connected generate/benchmark run UNINSTALLS the app at the
                // end: use an emulator or a Google-synced device (anonymous data is lost), and
                // ANDROID_SERIAL=<serial> when several devices are connected.
                signingConfig = signingConfigs.getByName("debug")
                // Keep benchmark sessions out of the production Amplitude project.
                buildConfigField("String", "AMPLITUDE_KEY", "\"${localProps.getProperty("AMPLITUDE_DEBUG_KEY", "")}\"")
                // No mapping upload to Crashlytics from local benchmark/profile builds.
                configure<CrashlyticsExtension> { mappingFileUploadEnabled = false }
            }
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11

        // Backports java.time.* (API 26+) to minSdk 24 via L8. REQUIRED: kotlinx-datetime on
        // Android delegates to java.time, so TimeZone.<clinit> hard-crashes on API 24-25 without
        // it (NoClassDefFoundError: Ljava/time/ZoneOffset; — Crashlytics 52217411).
        // This is the app module, where dexing happens: L8 rewrites java.time -> j$.time across
        // ALL dependencies, so the 6 KMP library modules using kotlinx-datetime are covered here.
        // The KMP library plugin (com.android.kotlin.multiplatform.library) exposes no
        // compileOptions block, so this is also the only place it CAN be declared.
        isCoreLibraryDesugaringEnabled = true
    }
}

baselineProfile {
    // Generation needs a device; never run it as part of a plain assemble/bundle.
    automaticGenerationDuringBuild = false
    // Use startup-prof.txt (tests with includeInStartupProfile = true) for R8 DEX layout.
    dexLayoutOptimization = true
}

dependencies {
    // Producer module for baseline-prof.txt / startup-prof.txt (run :androidApp:generateBaselineProfile).
    baselineProfile(projects.baselineprofile)
    // Explicit instead of transitive: installs the profile on API 24-27 and sideloaded installs,
    // and provides the ProfileInstallReceiver that Macrobenchmark/BaselineProfileRule talk to.
    implementation(libs.androidx.profileinstaller)

    // Core library desugaring runtime (j$.time etc). Pairs with isCoreLibraryDesugaringEnabled
    // above; the standard variant is required because it carries java.time
    // (desugar_jdk_libs_minimal does NOT — it is java.util.function only).
    coreLibraryDesugaring(libs.desugar.jdk.libs)

    // composeApp KMP library — provides all shared KMP code + actuals
    implementation(projects.composeApp)

    // Direct deps on core+feature modules — needed because composeApp uses `implementation`
    // (non-transitive). androidApp references types from these modules directly in
    // GistiAndroidApplication (AnalyticsTracker), AndroidAppModule (ChecklistReminderScheduler,
    // ChecklistRepository), and the moved widget code.
    implementation(projects.core.common.api)
    implementation(projects.core.common.impl)
    implementation(projects.core.datastore.api)
    implementation(projects.core.datastore.impl)
    implementation(projects.core.designsystem)
    implementation(projects.core.navigation.api)
    implementation(projects.core.navigation.impl)
    implementation(projects.core.remoteconfig.api)
    implementation(projects.core.remoteconfig.impl)
    implementation(projects.feature.analyze)
    implementation(projects.feature.checklist)
    implementation(projects.feature.create)
    implementation(projects.feature.debug)
    implementation(projects.feature.home)
    implementation(projects.feature.onboarding)
    implementation(projects.feature.paywall)
    implementation(projects.feature.settings)
    implementation(projects.feature.sharing)
    implementation(projects.feature.splash)
    implementation(projects.feature.updatefeed)
    implementation(projects.feature.user)

    // Android UI essentials
    implementation(libs.androidx.activity.compose)
    debugImplementation(libs.androidx.compose.ui.tooling)

    // Glance for App Widgets (widget code lives in androidApp)
    implementation(libs.glance)
    implementation(libs.glance.appwidget)

    // WorkManager for widget sync
    implementation(libs.workmanager)

    // Google Play In-App Review
    implementation(libs.play.review.ktx)

    // Amplitude Analytics
    implementation(libs.amplitude.analytics)
    implementation(libs.play.services.appset)

    // Firebase — Android only
    implementation(platform(libs.firebase.bom))
    implementation(libs.firebase.analytics)
    implementation(libs.firebase.crashlytics)
    implementation(libs.firebase.config)

    // Koin Android — for androidContext() / androidLogger() in startKoin
    // koin-android pulls in koin-core transitively
    implementation(libs.koin.android)

    // JVM unit tests (Robolectric). `testImplementation` is a test-only configuration — none of
    // these artifacts reach debugRuntimeClasspath / releaseRuntimeClasspath.
    // Robolectric is needed here (and not in :composeApp) because the invariant under test lives in
    // the APK's MERGED manifest, which only the application module produces.
    testImplementation(libs.junit)
    testImplementation(libs.kotlin.testJunit)
    testImplementation(libs.robolectric)

    // Android UI Tests
    androidTestImplementation(libs.androidx.testExt.junit)
    androidTestImplementation(libs.androidx.espresso.core)
    androidTestImplementation(libs.androidx.compose.ui.test.junit4)
    androidTestImplementation(libs.androidx.test.uiautomator)
    debugImplementation(libs.androidx.compose.ui.test.manifest)

    // Test Orchestrator - runs each test in isolated process
    androidTestUtil(libs.androidx.test.orchestrator)

    // MockK - mocking library for Kotlin
    androidTestImplementation(libs.mockk.android)
    androidTestImplementation(libs.mockk.agent)
}
